package com.contextgraph.service; import com.contextgraph.model.*; import com.contextgraph.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.security.MessageDigest; import java.util.*; import java.util.HexFormat; @Service public class DocumentService{final DocumentRepository docs;final UserRepository users;final DocumentExtractionService extractor;final MetadataService meta;final Path storage;public DocumentService(DocumentRepository d,UserRepository u,DocumentExtractionService e,MetadataService m,@Value("${app.storage.local-dir}")String s){docs=d;users=u;extractor=e;meta=m;storage=Path.of(s);}public List<Document>list(String email){return docs.findByOwnerIdOrderByCreatedAtDesc(user(email).getId());}public Document upload(String email,MultipartFile f)throws Exception{if(f.isEmpty())throw new IllegalArgumentException("The uploaded file is empty.");if(f.getSize()>25L*1024*1024)throw new IllegalArgumentException("Maximum file size is 25 MB.");User u=user(email);String sum=sha(f.getBytes());if(docs.existsByChecksumAndOwnerId(sum,u.getId()))throw new IllegalArgumentException("This file is already in your ContextGraph.");String stored=UUID.randomUUID()+"-"+safe(f.getOriginalFilename());Files.createDirectories(storage);Files.copy(f.getInputStream(),storage.resolve(stored),StandardCopyOption.REPLACE_EXISTING);String text=extractor.extractText(f);Map<String,Object>x=meta.analyze(text,f.getOriginalFilename());Document d=new Document();d.setOriginalName(f.getOriginalFilename()==null?"unnamed":f.getOriginalFilename());d.setStoredName(stored);d.setContentType(f.getContentType());d.setSizeBytes(f.getSize());d.setExtractedText(text);d.setKeywords(String.join(",",(List<String>)x.get("keywords")));d.setEntities(String.join(",",(List<String>)x.get("entities")));d.setDates(String.join(",",(List<String>)x.get("dates")));d.setTopic((String)x.get("topic"));d.setChecksum(sum);d.setOwner(u);return docs.save(d);}public Document get(String email,Long id){return docs.findByIdAndOwnerId(id,user(email).getId()).orElseThrow(()->new IllegalArgumentException("Document not found."));}public void delete(String email,Long id)throws Exception{Document d=get(email,id);Files.deleteIfExists(storage.resolve(d.getStoredName()));docs.delete(d);}User user(String e){return users.findByEmailIgnoreCase(e).orElseThrow(()->new IllegalArgumentException("User account not found."));}String safe(String n){return n==null?"file":n.replaceAll("[^a-zA-Z0-9._-]","_");}String sha(byte[]b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}}